// Data Hazard: RAW (Read After Write) Dependency
// Pipelined stages overlap: IF, ID, EX, MEM, WB
ADD R3, R1, R2       // I1: Writes R3 in WB
SUB R4, R3, R5       // I2: Reads R3 in ID/EX
AND R6, R4, R7       // I3: Reads R4 in ID/EX

// Hazard occurs when I2 tries to read R3
// before I1 has written R3 back to register file.
// Mitigation: Pipeline Stall (NOP) or Operand Forwarding.

// ---

// Control Hazard (Branch Dependency)
CMP R1, #0
BNE Target_A         // Branch Instruction (Executed in EX)
ADD R5, R5, #1       // Delay Slot 1 (Executed/Flushed if branch taken)
SUB R6, R6, #2       // Delay Slot 2
Target_A:
MUL R7, R7, R8

// Branch prediction mitigates pipeline flush latency.

// ---

// Hazard Mitigation: Operand Forwarding (Bypass)
// Feeds result directly from EX/MEM stage output register.
MUL R10, R1, R2      // I1: R10 computed in EX
ADD R11, R10, R3     // I2: R10 needed in EX input stage
// R10 value is "forwarded" from I1's EX stage
// output register directly to I2's EX input.
STORE R11, 0(R4)
